initScript:
await ManagerApi.ready();
assert(ftpHost, 'ftpHost is required');
return { message: 'init done' };

tests.scriptText:
const raw = await ManagerApi.call('ftp_probe', { host: ftpHost, user: ftpUser || '', pass: ftpPassword || '' });
const data = JSON.parse(raw || '{}');
return {
  probeRaw: raw,
  message: `snapshot captured`
};

const data = JSON.parse(probeRaw || '{}');
const p21 = data?.ports?.['21'];
return {
  port21Open: !!p21?.open,
  message: p21?.open ? `21 open, banner=${p21?.banner || '(empty)'}` : `21 closed, reason=${p21?.error || '(unknown)'}`
};

if (!port21Open) return { message: 'pass: port 21 is closed, skip FEAT test' };
const data = JSON.parse(probeRaw || '{}');
const feat = data?.feat?.response || '(empty)';
return { message: `FEAT response=${feat}` };

if (!port21Open) return { message: 'pass: port 21 is closed, skip login test' };
if (!ftpUser || !ftpPassword) return { message: 'pass: ftpUser/ftpPassword not provided, skip login test' };
const data = JSON.parse(probeRaw || '{}');
const plain = data?.login_plain || {};
const tls = data?.login_tls || {};
const authSupported = !!(data?.auth_tls?.supported);
const plainText = `plain=${plain?.ok?'ok':'fail'}; USER=${plain?.user_response || '(empty)'}; PASS=${plain?.pass_response || '(empty)'}`;
if (!authSupported || !tls?.tested) return { message: plainText + '; TLS login=pass(not tested)' };
const tlsText = `TLS=${tls?.ok?'ok':'fail'}; USER=${tls?.user_response || '(empty)'}; PASS=${tls?.pass_response || '(empty)'}`;
return { message: plainText + '; ' + tlsText };

if (!port21Open) return { authTlsSupported: false, authTlsState: 'skip', message: 'pass: port 21 is closed, skip AUTH TLS test' };
const data = JSON.parse(probeRaw || '{}');
const auth = data?.auth_tls || {};
const state = auth?.state || (auth?.supported ? 'supported' : 'unknown');
return {
  authTlsSupported: !!auth?.supported,
  authTlsState: state,
  message: `AUTH TLS state=${state}, response=${auth?.response || '(empty)'}`
};

if (!port21Open) return { tls21Ok: false, message: 'pass: port 21 is closed, skip TLS handshake test' };
if (!authTlsSupported) {
  if (authTlsState === 'need_login') return { tls21Ok: false, message: 'pass: AUTH TLS requires login first, skip TLS handshake test' };
  return { tls21Ok: false, message: 'pass: AUTH TLS unsupported/unknown, skip TLS handshake test' };
}
const data = JSON.parse(probeRaw || '{}');
const t = data?.tls_on_21;
return {
  tls21Ok: !!t?.ok,
  message: `TLS21=${t?.ok?'ok':'fail'}, detail=${t?.error || '(none)'}`
};

const data = JSON.parse(probeRaw || '{}');
const p = data?.ports?.['990'];
return {
  port990Open: !!p?.open,
  message: p?.open ? '990 open' : `990 closed, reason=${p?.error || '(unknown)'}`
};

if (!port990Open) return { tls990Ok: false, message: 'pass: port 990 is closed, skip TLS990 test' };
const data = JSON.parse(probeRaw || '{}');
const t = data?.tls_on_990;
return {
  tls990Ok: !!t?.ok,
  message: `TLS990=${t?.ok?'ok':'fail'}, detail=${t?.error || '(none)'}`
};

const data = JSON.parse(probeRaw || '{}');
const p = data?.ports?.['22'];
return {
  port22Open: !!p?.open,
  message: p?.open ? '22 open' : `22 closed, reason=${p?.error || '(unknown)'}`
};

if (!port22Open) return { isSsh22: false, message: 'pass: port 22 is closed, skip SSH banner test' };
const data = JSON.parse(probeRaw || '{}');
const p = data?.ports?.['22'];
return {
  isSsh22: !!p?.is_ssh,
  message: `22 banner=${p?.banner || '(empty)'}, is_ssh=${p?.is_ssh?'yes':'no'}`
};

const available = [];
if (port21Open && authTlsSupported && tls21Ok) available.push('ftps_explicit');
if (port21Open && authTlsState === 'need_auth_first') available.push('ftps_explicit(candidate)');
if (port21Open && (!authTlsSupported || authTlsState === 'need_login' || authTlsState === 'unknown')) available.push('ftp');
if (port990Open && tls990Ok) available.push('ftps_implicit');
if (port22Open && isSsh22) available.push('sftp');
const uniq = [...new Set(available)];
return { message: `available=${uniq.join(',') || '(none)'}` };
